INSERT OR REPLACE INTO governed_memory_entries (id, scope, property_id, fleet_key, ledger_key, summary, structured_payload_json, source_system, created_by, confidence, status, dedupe_signature, parent_entry_id, originating_candidate_id, created_at, updated_at) VALUES ('mem_fl4gw_captain_avasa_activation', 'property', 'a1e35a67-3040-4335-9cb9-d51219247b2e', NULL, NULL, 'Captain Avasa is activated for Avasa Grove West (FL4GW) as a portfolio,spotlight Captain. The Captain owns an evidence-backed Log, daily support-lane awareness, source freshness, recovery questions, and action follow-through across operations, marketing, search, content, reputation, and experience validation. Current designation: Spotlight.', '{"property_code":"FL4GW","property_name":"Avasa Grove West","captain":"Captain Avasa","activation_date":"2026-05-04","scope_type":"portfolio,spotlight","source_label":"Portfolio; 2026-05 Spotlight | Spotlight | Florida","designation":"Spotlight","market":"Florida","operating_charge":"Own the full property-life read: operational truth, demand, inventory, pricing/concessions, source performance, website/content/search/entity quality, experience validation, action follow-through, and memory.","required_questions":["What changed in the last 30 days?","What recovery math is required to get exposure below 10%?","Which traffic/source mix and spend shift supports that recovery?","Should pricing, concessions, operations, or advertising move first?","What exact web/content/SEO/local actions are urgent?","Are make-readies, hold times, reviews, images, source quality, or people/process issues constraining recovery?"],"support_lanes":["source_scout","truth_reconciler","inventory_watch","funnel_watch","media_watch","reputation_watch","navigator_watch","experience_watch","boatswain","logkeeper","supervisor_scribe"],"source_authority_posture":"Data Pond governs internal facts; Marketing BI and DataForSEO provide advisory and market/search evidence; memory must reconcile against current source-of-record values."}', 'captain_activation', 'captain-roster-standup', 0.9, 'active', 'captain_activation:FL4GW:2026-05-04', NULL, NULL, '2026-05-04T00:00:00Z', '2026-05-04T00:00:00Z');

